-  call agent start "$name" --kind "$kind" --pane "$pane" >/dev/null
+  call agent start "$name" --kind "$kind" --pane "$pane" -- "${argv[@]}" >/dev/null
+}
+
+# Runs detached (type = "shell"), so report through herdr, not the terminal.
+cmd_attention() {
+  local target
+  target=$("$herdr" agent list 2>/dev/null | jq -r '
+    [.result.agents[]? | select((.focused | not) and (.agent_status == "blocked" or .agent_status == "done"))]
+    | sort_by([.agent_status == "blocked", .state_change_seq]) | last | .pane_id // empty') || true
+  if [ -n "$target" ]; then
+    "$herdr" agent focus "$target" >/dev/null
+  else
+    "$herdr" notification show "No agents need attention" >/dev/null
+  fi
+}
+
+# Runs detached (type = "shell") with the clipboard on stdin.
+cmd_paste() {
+  local text
+  text=$(cat)
+  [ -n "$text" ] || return 0
+  # Drop an embedded end marker so pasted text can't end the paste early.
+  text=${text//$'\e[201~'/}
+  "$herdr" pane send-text "${HERDR_ACTIVE_PANE_ID:?}" $'\e[200~'"$text"$'\e[201~' >/dev/null
+}
+
+# Runs detached from zsh hooks (herdr-tab-name.zsh), so failures stay silent.
+# Hooks fire faster than renames finish, so a per-pane lock and the hook's
+# timestamp (SEQ) drop renames that a later hook already superseded.
+cmd_tab_name() {
+  local seq=$1 new=$2 state last tab label known ours=
+  shift 2
+  state=${XDG_RUNTIME_DIR:-${TMPDIR:-/tmp}}/herdr-tab-name
+  mkdir -p "$state"
+  state=$state/${HERDR_PANE_ID//[^A-Za-z0-9]/_}
+  exec 9>>"$state.lock"
+  flock 9
+  last=$(cat "$state" 2>/dev/null || true)
+  [ "${last:-0}" -lt "$seq" ] || return 0
+  printf '%s\n' "$seq" >"$state"
+
+  tab=$("$herdr" pane get "${HERDR_PANE_ID:-}" 2>/dev/null | jq -r '.result.pane.tab_id // empty') || return 0
+  [ -n "$tab" ] || return 0
+  label=$("$herdr" tab get "$tab" 2>/dev/null | jq -r '.result.tab.label // empty') || return 0
+  [ "$label" != "$new" ] || return 0
+  if ! [[ $label =~ ^[0-9]+$ ]]; then
+    for known; do
+      if [ "$label" = "$known" ]; then ours=1; fi
+    done
+    [ -n "$ours" ] || return 0
+  fi
+  "$herdr" tab rename "$tab" "$new" >/dev/null 2>&1 || true
 }

 case ${1:-} in
   project) shift; cmd_project "$@" ;;
   agent) shift; cmd_agent "$@" ;;
-  *) fail "usage: herdr-launch {project|agent KIND...}" ;;
+  attention) cmd_attention ;;
+  paste) cmd_paste ;;
+  tab-name) shift; cmd_tab_name "$@" ;;
+  *) fail "usage: herdr-launch {project|agent 'KIND [ARG...]'...|attention|paste|tab-name SEQ LABEL [KNOWN...]}" ;;
 esac
